void sctp_assoc_update(struct sctp_association *asoc, struct sctp_association *new) {
    /* Copy new parameters from 'new' to 'asoc' */
    asoc->rwnd = new->rwnd;
    asoc->ssthresh = new->ssthresh;
    asoc->cwnd = new->cwnd;
    asoc->mtu = new->mtu;

    /* Remove peer addresses in 'asoc' not in 'new' */
    struct sctp_sockaddr *tmp, *next;
    list_for_each_entry_safe(tmp, next, &asoc->peer_addrs, list) {
        int found = 0;
        list_for_each_entry(next, &new->peer_addrs, list) {
            if (!memcmp(&tmp->addr, &next->addr, sizeof(tmp->addr))) {
                found = 1;
                break;
            }
        }
        if (!found) {
            list_del(&tmp->list);
            kfree(tmp);
        }
    }

    /* Update TSN and clear SSN map if association is established */
    if (asoc->state == SCTP_STATE_ESTABLISHED) {
        asoc->next_tsn = new->next_tsn;
        sctp_ssn_map_clear(asoc);
        sctp_flush_ulp_queue(asoc);
        asoc->error_count = 0;
    } else {
        /* Add new peer addresses */
        list_for_each_entry(tmp, &new->peer_addrs, list) {
            int found = 0;
            list_for_each_entry(next, &asoc->peer_addrs, list) {
                if (!memcmp(&tmp->addr, &next->addr, sizeof(tmp->addr))) {
                    found = 1;
                    break;
                }
            }
            if (!found) {
                struct sctp_sockaddr *addr_copy = kzalloc(sizeof(*addr_copy), GFP_KERNEL);
                if (addr_copy) {
                    memcpy(&addr_copy->addr, &tmp->addr, sizeof(tmp->addr));
                    list_add_tail(&addr_copy->list, &asoc->peer_addrs);
                }
            }
        }
        asoc->assoc_id = new->assoc_id;
        sctp_ssn_map_init(asoc);
    }

    /* Copy authentication parameters and keys */
    asoc->auth_key = new->auth_key;
    asoc->auth_chunk_list = new->auth_chunk_list;
}

void sctp_update_association(struct sctp_association *asoc, struct sctp_association *new) {
    struct sctp_transport *t, *tmp;

    /* Copy new parameters from 'new' to 'asoc' */
    asoc->rwnd = new->rwnd;
    asoc->ssthresh = new->ssthresh;
    asoc->c.sack_delay = new->c.sack_delay;
    asoc->c.sack_freq = new->c.sack_freq;
    asoc->c.pathmaxrxt = new->c.pathmaxrxt;

    /* Remove peer addresses in 'asoc' that are not in 'new' */
    sctp_transport_for_each_safe(t, tmp, &asoc->peer.transport_addr_list) {
        int found = 0;
        sctp_transport_for_each(struct sctp_transport *nt, &new->peer.transport_addr_list) {
            if (sctp_addr_cmp(&t->ip_all, &nt->ip_all, SCTP_ADDR_CMP_NOPORT)) {
                found = 1;
                break;
            }
        }
        if (!found) {
            sctp_transport_put(t);
            sctp_list_del(&t->transports, &asoc->peer.transport_addr_list);
        }
    }

    if (asoc->state == SCTP_STATE_ESTABLISHED) {
        /* Update next TSN and clear SSN map */
        asoc->c.tsn_next = new->c.tsn_next;
        sctp_ssnmap_clear(&asoc->ssnmap);
        sctp_ulpq_flush(&asoc->ulpq);
        asoc->error_count = 0;
    } else {
        /* Add new peer addresses */
        sctp_transport_for_each(t, &new->peer.transport_addr_list) {
            if (!sctp_transport_lookup(&asoc->peer, t->ip_all)) {
                sctp_transport_add(&asoc->peer, sctp_transport_clone(t));
            }
        }

        /* Update SSN map and association ID */
        if (!asoc->ssnmap.size) {
            sctp_ssnmap_init(&asoc->ssnmap, new->ssnmap.size);
        }

        asoc->assoc_id = new->assoc_id;
    }

    /* Update SCTP-AUTH parameters */
    if (new->auth_info.auth_key) {
        if (asoc->auth_info.auth_key) {
            sctp_free_auth_key(asoc->auth_info.auth_key);
        }

        asoc->auth_info.auth_key = sctp_clone_auth_key(new->auth_info.auth_key);
        asoc->auth_info.active_keyid = new->auth_info.active_keyid;
        asoc->auth_info.peer_support = new->auth_info.peer_support;
        asoc->auth_info.peer_hmacs = new->auth_info.peer_hmacs;
    }
}

