    list_for_each_entry_safe(t, temp_t, &asoc->peer.transport_addr_list, list) {
        int found = 0;
        list_for_each_entry(struct sctp_transport, new_t, &new->peer.transport_addr_list, list) {
            if (!memcmp(&t->saddr, &new_t->saddr, sizeof(t->saddr))) {
                found = 1;
                break;
            }
        }
        if (!found) {
            list_del(&t->list);
            kmem_cache_free(SCTP_TRANSPORT, t);
        }
    }

    if (asoc->state == SCTP_ESTABLISHED) {
        asoc->next_tsn = new->next_tsn;
        sctp_ssnmap_clear(&asoc->ssnmap);
        sctp_ulpq_flush(&asoc->ulpq);
        asoc->error_count = 0;
    } else {
