        list_for_each_entry(t, &new->peer.transport_addr_list, list) {
            int found = 0;
            list_for_each_entry(struct sctp_transport, new_t, &asoc->peer.transport_addr_list, list) {
                if (!memcmp(&t->saddr, &new_t->saddr, sizeof(t->saddr))) {
                    found = 1;
                    break;
                }
            }
            if (!found) {
                struct sctp_transport *new_t = kmem_cache_alloc(SCTP_TRANSPORT, GFP_KERNEL);
                if (new_t) {
                    memcpy(&new_t->saddr, &t->saddr, sizeof(t->saddr));
                    new_t->state = t->state;
                    list_add(&new_t->list, &asoc->peer.transport_addr_list);
                }
            }
        }

        if (!list_empty(&new->ssnmap)) {
            sctp_ssnmap_clear(&asoc->ssnmap);
            asoc->ssnmap = new->ssnmap;
            INIT_LIST_HEAD(&new->ssnmap);
        }

        asoc->assoc_id = new->assoc_id;
