void sctp_assoc_update(struct sctp_association *asoc, struct sctp_association *new) {
    /* Copy new parameters from 'new' to 'asoc' */
    asoc->next_tsn = new->next_tsn;
    asoc->ssn_next = new->ssn_next;
    asoc->c.sack_delay = new->c.sack_delay;
    asoc->c.sack_freq = new->c.sack_freq;
    asoc->c.pmtu = new->c.pmtu;

    /* Remove peer addresses in 'asoc' that are not in 'new' */
    struct sctp_transport *t, *next_t;
    for (t = asoc->peer.transports; t; t = next_t) {
        int found = 0;
        struct sctp_transport *tmp;
        for (tmp = new->peer.transports; tmp; tmp = tmp->next) {
            if (sctp_cmp_addr(&t->ip_all, &tmp->ip_all)) {
                found = 1;
                break;
            }
        }
        if (!found) {
            sctp_transport_put(t);
        }
        next_t = t->next;
    }

    /* Add new peer addresses from 'new' */
    for (t = new->peer.transports; t; t = t->next) {
        struct sctp_transport *tmp;
        int found = 0;
        for (tmp = asoc->peer.transports; tmp; tmp = tmp->next) {
            if (sctp_cmp_addr(&t->ip_all, &tmp->ip_all)) {
                found = 1;
                break;
            }
        }
        if (!found) {
            sctp_transport_add(asoc, t);
        }
    }

    /* If association is established */
    if (asoc->state >= SCTP_STATE_ESTABLISHED) {
        asoc->next_tsn = new->next_tsn;
        sctp_tsnmap_clear(&asoc->tsn_map);
        sctp_ulpq_flush(&asoc->ulpq);
        asoc->error_count = 0;
    } else {
        asoc->assoc_id = new->assoc_id;
    }

    /* Update SCTP-AUTH related parameters */
    asoc->auth_hmac_alg = new->auth_hmac_alg;
    memcpy(asoc->shared_keys, new->shared_keys, sizeof(asoc->shared_keys));
    asoc->active_keyid = new->active_keyid;
}

void sctp_association_update(struct sctp_association *asoc, struct sctp_association *new) {
    /* Copy new parameters from 'new' to 'asoc' */
    asoc->rwnd = new->rwnd;
    asoc->ssthresh = new->ssthresh;
    asoc->cwnd = new->cwnd;
    asoc->flight_size = new->flight_size;
    asoc->partial_failure = new->partial_failure;

    /* Remove addresses from 'asoc' not in 'new' */
    struct sctp_transport *t1, *t2;
    for (t1 = asoc->peer.transports; t1; t1 = t2) {
        t2 = t1->next;
        int found = 0;
        for (struct sctp_transport *t = new->peer.transports; t; t = t->next) {
            if (sctp_cmp_addr(t1->ipaddr, t->ipaddr)) {
                found = 1;
                break;
            }
        }
        if (!found) {
            sctp_list_del(t1);
            sctp_transport_free(t1);
        }
    }

    if (asoc->state == SCTP_STATE_ESTABLISHED) {
        asoc->next_tsn = new->next_tsn;
        asoc->ssn_map = new->ssn_map;
        sctp_ulpq_flush(&asoc->ulpq);
        asoc->error_count = 0;
    } else {
        /* Add new peer addresses */
        for (struct sctp_transport *t = new->peer.transports; t; t = t->next) {
            int found = 0;
            for (struct sctp_transport *t2 = asoc->peer.transports; t2; t2 = t2->next) {
                if (sctp_cmp_addr(t->ipaddr, t2->ipaddr)) {
                    found = 1;
                    break;
                }
            }
            if (!found) {
                struct sctp_transport *new_transport = sctp_transport_clone(t);
                if (new_transport)
                    sctp_list_add_tail(&asoc->peer.transports, &new_transport->list);
            }
        }
        sctp_ssnmap_init(asoc->ssn_map);
        asoc->assoc_id = new->assoc_id;
    }

    /* Update SCTP-AUTH parameters */
    sctp_auth_update_key(asoc, new->auth_keys);
    asoc->active_keyid = new->active_keyid;
}
